function maxWindow(a,k) {
  if(!Number.isInteger(k)||k<1||k>a.length)return 
null;
  let s=a.slice(0,k).reduce((x,y)=>x+y,0),best=s;
  for(let i=k;i<a.length;i++){
    s+=a[i]-a[i-k];best=Math.max(best,s);
  }return best;
}

static Long maxWindow(int[] a,int k) {
  if(k<1||k>a.length)return null;
  long s=0;for(int i=0;i<k;i++)s+=a[i];long best=s;
  for(int i=k;i<a.length;i++){
    s+=(long)a[i]-a[i-k];best=Math.max(best,s);
  }return best;
}
